<script lang="ts">
	import { Check, KeyRound, LoaderCircle, LockKeyhole, UserRound } from '@lucide/svelte';
	import type { DeviceConfig } from '$lib/device-config';
	import { createUserConfigComponent, getEdgeConfig } from '$lib/services/rts-api';
	let {config}:{config:DeviceConfig|null}=$props();
	let oldPassword=$state('');let newPassword=$state('');let confirmPassword=$state('');let saving=$state(false);let error=$state('');let notice=$state('');
	async function sha256(value:string){const bytes=new TextEncoder().encode(value);const hash=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(hash)).map((byte)=>byte.toString(16).padStart(2,'0')).join('')}
	async function currentHash(){const edge=await getEdgeConfig();return String(edge.components.admin?.factoryId==='Controller.io.openems.edge.account.config'?edge.components.admin.properties?.alias??'':(config?.rts?.systemInfo?.defaultUser?.passwordHash??''))}
	async function changePassword(){error='';notice='';if(!oldPassword)return error='Enter the current password.';if(newPassword.length<6)return error='New password must contain at least 6 characters.';if(newPassword!==confirmPassword)return error='Password confirmation does not match.';saving=true;try{if(await sha256(oldPassword)!==await currentHash())throw new Error('Old password is not correct.');await createUserConfigComponent('Controller.io.openems.edge.account.config',{apply:'true',factoryPid:'Controller.io.openems.edge.account.config',id:'admin',alias:await sha256(newPassword),propertylist:'id,alias'});oldPassword='';newPassword='';confirmPassword='';notice='Password changed successfully. Please sign in again on the RTS device.';}catch(cause){error=cause instanceof Error?cause.message:'Unable to change the RTS password.';}finally{saving=false;}}
</script>
<section class="page"><div class="head"><h2><UserRound size={23}/>RTS Account</h2><p>Administrator credentials stored by the RTS account controller.</p></div>{#if notice}<div class="notice"><Check size={16}/>{notice}</div>{/if}{#if error}<div class="error">{error}</div>{/if}<div class="layout"><section class="profile"><span><UserRound size={25}/></span><div><small>Username</small><strong>admin</strong><p>Controller.io.openems.edge.account.config</p></div></section><form onsubmit={(event)=>{event.preventDefault();void changePassword();}}><header><span><KeyRound size={20}/></span><div><h3>Change password</h3><p>The stored value is a SHA-256 hash in the component alias.</p></div></header><div class="body"><label>Current password<div><LockKeyhole size={16}/><input type="password" bind:value={oldPassword} autocomplete="current-password"/></div></label><label>New password<div><LockKeyhole size={16}/><input type="password" bind:value={newPassword} autocomplete="new-password"/></div><small>Minimum 6 characters</small></label><label>Confirm new password<div><LockKeyhole size={16}/><input type="password" bind:value={confirmPassword} autocomplete="new-password"/></div></label></div><footer><button disabled={saving}>{#if saving}<LoaderCircle size={16}/>{:else}<Check size={16}/>{/if}{saving?'Saving…':'Change password'}</button></footer></form></div></section>
<style>.page{animation:in .18s ease}.head h2{display:flex;align-items:center;gap:9px;margin:0;color:#172b4d;font-size:24px;font-weight:500}.head p{margin:7px 0 18px;color:#718096;font-size:16px}.notice,.error{margin-bottom:13px;padding:10px 12px;border-radius:8px;font-size:13px}.notice{display:flex;align-items:center;gap:7px;color:#28784e;background:#f2fbf5;border:1px solid #cae7d5}.error{color:#b42318;background:#fff1f0;border:1px solid #f3cac6}.layout{display:grid;grid-template-columns:minmax(240px,.65fr) minmax(380px,1.35fr);gap:15px}.profile,form{border:1px solid #e1e7f0;border-radius:11px;background:#fff}.profile{display:flex;align-items:flex-start;gap:12px;padding:18px}.profile>span,form header>span{display:grid;place-items:center;width:39px;height:39px;border-radius:10px;color:#2754b5;background:#eaf0ff}.profile small,.profile strong{display:block}.profile small{color:#8792a4;font-size:12px}.profile strong{margin-top:4px;color:#31415c;font-size:17px;font-weight:500}.profile p{margin:8px 0 0;color:#8792a4;font-size:12px;word-break:break-word}form{overflow:hidden}form header{display:flex;align-items:center;gap:10px;padding:16px 18px;border-bottom:1px solid #edf0f4}form h3{margin:0;color:#31415c;font-size:16px;font-weight:500}form header p{margin:4px 0 0;color:#8792a4;font-size:12px}.body{display:grid;grid-template-columns:1fr 1fr;gap:13px;padding:18px}.body label:first-child{grid-column:1/-1}.body label{display:grid;gap:6px;color:#536078;font-size:13px}.body label>div{display:flex;align-items:center;height:39px;border:1px solid #d7dfeb;border-radius:7px;color:#7d899b;background:#fff}.body label>div:focus-within{border-color:#3764c0;box-shadow:0 0 0 3px rgba(55,100,192,.12)}.body svg{margin-left:10px}.body input{min-width:0;flex:1;height:100%;padding:0 10px;border:0;outline:0;color:#273853;background:transparent;font:inherit}.body small{color:#8b96a7}footer{display:flex;justify-content:flex-end;padding:12px 18px;border-top:1px solid #edf0f4}footer button{display:flex;align-items:center;gap:7px;height:38px;padding:0 13px;border:0;border-radius:8px;color:#fff;background:#1749ad;font:inherit;cursor:pointer}footer button:disabled{opacity:.55}@keyframes in{from{opacity:0;transform:translateY(4px)}}@media(max-width:900px){.layout{grid-template-columns:1fr}}@media(max-width:600px){.body{grid-template-columns:1fr}.body label:first-child{grid-column:auto}}</style>
